def dependencies_valid(nodes: list[str], edges: list[tuple[str,str]]) -> bool:
    if len(set(nodes))!=len(nodes): return False
    degree={x:0 for x in nodes}; graph={x:[] for x in nodes}
    for a,b in edges:
        if a not in degree or b not in degree: return False
        graph[a].append(b);degree[b]+=1
    queue=[x for x in nodes if degree[x]==0];seen=0
    while queue:
        x=queue.pop();seen+=1
        for y in graph[x]:
            degree[y]-=1
            if degree[y]==0:queue.append(y)
    return seen==len(nodes)
